-- Curated applied questions for Philippine Geography & History and SHS Communication, Life Skills, and History.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en, quiz_fil=v.quiz_fil, explanation_en=v.explanation_en,
    explanation_fil=v.explanation_fil, options=v.options::jsonb
FROM (VALUES
 ($$starter-ap-archipelago$$,$$A student sees a map with thousands of islands. Which geographic term describes a chain or group of islands such as the Philippines?$$,$$Nakakita ang mag-aaral ng mapang may libo-libong pulo. Anong katawagang heograpikal ang tumutukoy sa pangkat o hanay ng mga pulo gaya ng Pilipinas?$$,$$An archipelago is a group or chain of islands.$$,$$Ang archipelago ay pangkat o hanay ng mga pulo.$$,$$[{"en":"An archipelago","fil":"Archipelago","correct":true},{"en":"A peninsula","fil":"Tangway","correct":false},{"en":"A plateau","fil":"Talampas","correct":false},{"en":"A desert basin","fil":"Disyerto","correct":false}]$$),
 ($$starter-ap-island-groups$$,$$A relief map labels the country’s three major island groups. Which set should appear?$$,$$Nilalagyan ng pangalan sa mapa ang tatlong pangunahing pangkat ng pulo ng bansa. Aling pangkat ang dapat makita?$$,$$The Philippines is commonly grouped into Luzon, Visayas, and Mindanao.$$,$$Karaniwang hinahati ang Pilipinas sa Luzon, Visayas, at Mindanao.$$,$$[{"en":"Luzon, Visayas, and Mindanao","fil":"Luzon, Visayas, at Mindanao","correct":true},{"en":"Luzon, Palawan, and Sulu only","fil":"Luzon, Palawan, at Sulu lamang","correct":false},{"en":"Visayas, Borneo, and Mindanao","fil":"Visayas, Borneo, at Mindanao","correct":false},{"en":"Luzon, Samar, and Panay only","fil":"Luzon, Samar, at Panay lamang","correct":false}]$$),
 ($$starter-ap-independence$$,$$A class exhibit marks the date Philippine independence was proclaimed in 1898. Which date belongs on the timeline?$$,$$Itinatampok sa klase ang petsa ng pagpapahayag ng kasarinlan ng Pilipinas noong 1898. Aling petsa ang dapat ilagay sa timeline?$$,$$The proclamation took place on June 12, 1898.$$,$$Naganap ang pagpapahayag noong Hunyo 12, 1898.$$,$$[{"en":"June 12, 1898","fil":"Hunyo 12, 1898","correct":true},{"en":"May 28, 1898","fil":"Mayo 28, 1898","correct":false},{"en":"February 2, 1987","fil":"Pebrero 2, 1987","correct":false},{"en":"July 4, 1946","fil":"Hulyo 4, 1946","correct":false}]$$),
 ($$starter-ap-flag-makers$$,$$A museum label names the women who sewed the Philippine flag in Hong Kong. Which names are historically associated with this work?$$,$$Binabanggit sa museo ang mga babaeng nagtahi ng watawat ng Pilipinas sa Hong Kong. Aling mga pangalan ang kaugnay ng gawaing ito?$$,$$Marcela Agoncillo, her daughter Lorenza, and Delfina Herbosa helped sew the flag.$$,$$Tumulong manahi ng watawat sina Marcela Agoncillo, anak niyang si Lorenza, at Delfina Herbosa.$$,$$[{"en":"Marcela Agoncillo, Lorenza Agoncillo, and Delfina Herbosa","fil":"Marcela Agoncillo, Lorenza Agoncillo, at Delfina Herbosa","correct":true},{"en":"Melchora Aquino, Gabriela Silang, and Gregoria de Jesus","fil":"Melchora Aquino, Gabriela Silang, at Gregoria de Jesus","correct":false},{"en":"Apolinario Mabini, Emilio Jacinto, and Artemio Ricarte","fil":"Apolinario Mabini, Emilio Jacinto, at Artemio Ricarte","correct":false},{"en":"Paz Marquez-Benitez, N.V.M. Gonzalez, and Nick Joaquin","fil":"Paz Marquez-Benitez, N.V.M. Gonzalez, at Nick Joaquin","correct":false}]$$),
 ($$starter-ap-flag-first-raised$$,$$A history class asks where the Philippine flag was first raised in battle and when. Which answer is correct?$$,$$Itinanong sa klase kung saan at kailan unang iwinagayway sa labanan ang watawat ng Pilipinas. Aling sagot ang tama?$$,$$The flag was first raised in battle at Alapan on May 28, 1898.$$,$$Unang iwinagayway sa labanan ang watawat sa Alapan noong Mayo 28, 1898.$$,$$[{"en":"Alapan, May 28, 1898","fil":"Alapan, Mayo 28, 1898","correct":true},{"en":"Kawit, June 12, 1898","fil":"Kawit, Hunyo 12, 1898","correct":false},{"en":"Malolos, February 2, 1899","fil":"Malolos, Pebrero 2, 1899","correct":false},{"en":"Manila, July 4, 1946","fil":"Maynila, Hulyo 4, 1946","correct":false}]$$),
 ($$starter-ap-anthem-composer$$,$$A student researches the music of the Philippine national anthem. Who composed the march’s music?$$,$$Nagsasaliksik ang mag-aaral tungkol sa musika ng pambansang awit ng Pilipinas. Sino ang bumuo ng musika ng martsa?$$,$$Julian Felipe composed the music for the march that became the national anthem.$$,$$Si Julian Felipe ang bumuo ng musika ng martsa na naging pambansang awit.$$,$$[{"en":"Julian Felipe","fil":"Julian Felipe","correct":true},{"en":"Jose Palma","fil":"Jose Palma","correct":false},{"en":"Andres Bonifacio","fil":"Andres Bonifacio","correct":false},{"en":"Juan Luna","fil":"Juan Luna","correct":false}]$$),
 ($$starter-ap-kawit$$,$$A visitor wants to see the site associated with the June 12, 1898 independence proclamation. Where should the visitor go?$$,$$Nais puntahan ng bisita ang lugar na kaugnay ng pagpapahayag ng kasarinlan noong Hunyo 12, 1898. Saan siya dapat pumunta?$$,$$The proclamation took place in Kawit, Cavite.$$,$$Naganap ang pagpapahayag sa Kawit, Cavite.$$,$$[{"en":"Kawit, Cavite","fil":"Kawit, Cavite","correct":true},{"en":"Malolos, Bulacan","fil":"Malolos, Bulacan","correct":false},{"en":"Alapan, Imus","fil":"Alapan, Imus","correct":false},{"en":"Dapitan, Zamboanga del Norte","fil":"Dapitan, Zamboanga del Norte","correct":false}]$$),
 ($$starter-ap-malolos$$,$$A researcher studies the legislative body of the First Philippine Republic. Where did the Malolos Congress meet?$$,$$Pinag-aaralan ng mananaliksik ang kapulungang tagapagbatas ng Unang Republika ng Pilipinas. Saan nagpulong ang Kongreso ng Malolos?$$,$$The Malolos Congress met in Bulacan during the First Philippine Republic.$$,$$Nagpulong sa Bulacan ang Kongreso ng Malolos noong Unang Republika ng Pilipinas.$$,$$[{"en":"Malolos, Bulacan","fil":"Malolos, Bulacan","correct":true},{"en":"Kawit, Cavite","fil":"Kawit, Cavite","correct":false},{"en":"Cebu City","fil":"Lungsod ng Cebu","correct":false},{"en":"Vigan, Ilocos Sur","fil":"Vigan, Ilocos Sur","correct":false}]$$),
 ($$starter-ap-primary-sources$$,$$A historian examines a letter written by a participant during the event being studied. How should this evidence be classified?$$,$$Sinusuri ng historyador ang liham na isinulat ng kalahok noong nagaganap ang pangyayaring pinag-aaralan. Paano ito inuuri?$$,$$A primary source was created during the period or event being studied.$$,$$Nilikha ang primary source noong panahong o pangyayaring pinag-aaralan.$$,$$[{"en":"A primary source","fil":"Primary source","correct":true},{"en":"A later textbook summary","fil":"Buod sa aklat na isinulat kalaunan","correct":false},{"en":"A fictional retelling","fil":"Kathang-isip na pagsasalaysay","correct":false},{"en":"A modern opinion with no period evidence","fil":"Makabagong opinyong walang ebidensiya mula sa panahong iyon","correct":false}]$$),
 ($$starter-ap-map-legend$$,$$A map uses a small blue line for rivers and a star for the capital. Where can readers learn what these symbols mean?$$,$$Gumagamit ang mapa ng asul na guhit para sa ilog at bituin para sa kabisera. Saan malalaman ng mambabasa ang kahulugan ng mga simbolo?$$,$$A map legend explains the symbols used on the map.$$,$$Ipinapaliwanag ng legend ng mapa ang mga simbolong ginamit.$$,$$[{"en":"The map legend","fil":"Legend ng mapa","correct":true},{"en":"The scale bar only","fil":"Scale bar lamang","correct":false},{"en":"The map title only","fil":"Pamagat lamang ng mapa","correct":false},{"en":"The border around the map","fil":"Hangganan sa paligid ng mapa","correct":false}]$$),
 ($$starter-ap-cardinal-directions$$,$$A hiker faces the sunrise in the east. Which direction is directly opposite?$$,$$Nakaharap sa silangan kung saan sumisikat ang araw ang isang naglalakad. Aling direksiyon ang katapat nito?$$,$$East and west are opposite cardinal directions.$$,$$Magkatapat na pangunahing direksiyon ang silangan at kanluran.$$,$$[{"en":"West","fil":"Kanluran","correct":true},{"en":"North","fil":"Hilaga","correct":false},{"en":"South","fil":"Timog","correct":false},{"en":"Northeast","fil":"Hilagang-silangan","correct":false}]$$),
 ($$starter-ap-latitude$$,$$A navigator needs coordinates north or south of the Equator. Which lines on a globe provide that measurement?$$,$$Kailangan ng navigator ng koordinat na pahilaga o patimog mula sa Ekwador. Aling mga guhit sa globo ang sumusukat nito?$$,$$Lines of latitude measure distance north or south of the Equator.$$,$$Sinusukat ng latitude ang layo pahilaga o patimog mula sa Ekwador.$$,$$[{"en":"Lines of latitude","fil":"Mga guhit ng latitude","correct":true},{"en":"Lines of longitude","fil":"Mga guhit ng longitude","correct":false},{"en":"Contour lines","fil":"Mga contour line","correct":false},{"en":"Time-zone borders","fil":"Mga hangganan ng time zone","correct":false}]$$),
 ($$starter-ap-longitude$$,$$A map user wants to compare a location east or west of Greenwich’s Prime Meridian. Which coordinate should they read?$$,$$Nais malaman ng gumagamit ng mapa kung gaano kalayo sa silangan o kanluran ng Prime Meridian ang isang lugar. Aling koordinat ang dapat basahin?$$,$$Longitude measures distance east or west of the Prime Meridian.$$,$$Sinusukat ng longitude ang layo pasilangan o pakanluran mula sa Prime Meridian.$$,$$[{"en":"Longitude","fil":"Longitude","correct":true},{"en":"Latitude","fil":"Latitude","correct":false},{"en":"Elevation","fil":"Elevation o taas mula sa dagat","correct":false},{"en":"Map scale","fil":"Scale ng mapa","correct":false}]$$),
 ($$starter-shs-communication-process$$,$$A student sends a clear announcement through a class group chat to classmates. In the communication process, what carries the message?$$,$$Nagpadala ang mag-aaral ng malinaw na anunsiyo sa group chat ng klase. Sa proseso ng komunikasyon, ano ang nagdadala ng mensahe?$$,$$The channel is the medium used to carry a message from sender to receiver.$$,$$Ang channel ang midyum na nagdadala ng mensahe mula sa nagpadala patungo sa tagatanggap.$$,$$[{"en":"The group chat is the channel.","fil":"Ang group chat ang channel.","correct":true},{"en":"The sender is the channel.","fil":"Ang sender ang channel.","correct":false},{"en":"The announcement’s purpose is the channel.","fil":"Ang layunin ng anunsiyo ang channel.","correct":false},{"en":"The receiver’s reaction is the channel.","fil":"Ang reaksiyon ng receiver ang channel.","correct":false}]$$),
 ($$starter-shs-communication-verbal$$,$$A team needs to explain task instructions precisely. Which choice is verbal communication?$$,$$Kailangang ipaliwanag nang tiyak ng pangkat ang mga tagubilin sa gawain. Alin ang verbal communication?$$,$$Verbal communication shares meaning through spoken or written words.$$,$$Nagbabahagi ng kahulugan ang verbal communication sa pamamagitan ng sinasalita o isinulat na mga salita.$$,$$[{"en":"Give the instructions aloud or in writing.","fil":"Sabihin o isulat ang mga tagubilin.","correct":true},{"en":"Point silently without words.","fil":"Ituro nang walang sinasabi.","correct":false},{"en":"Use only a facial expression.","fil":"Gumamit lamang ng ekspresyon ng mukha.","correct":false},{"en":"Stand in a particular posture without a message.","fil":"Tumayo sa isang postura nang walang mensahe.","correct":false}]$$),
 ($$starter-shs-communication-nonverbal$$,$$During a presentation, a speaker’s crossed arms and facial expression affect how the audience reads the message. What kind of cues are these?$$,$$Habang nag-uulat, naaapektuhan ng nakatiklop na braso at ekspresyon ng tagapagsalita kung paano inuunawa ng tagapakinig ang mensahe. Anong uri ng pahiwatig ang mga ito?$$,$$Gestures, facial expressions, and posture are nonverbal communication cues.$$,$$Mga di-berbal na pahiwatig ang kilos, ekspresyon ng mukha, at postura.$$,$$[{"en":"Nonverbal cues","fil":"Mga di-berbal na pahiwatig","correct":true},{"en":"Written vocabulary","fil":"Nakasulat na bokabularyo","correct":false},{"en":"The message channel only","fil":"Channel lamang ng mensahe","correct":false},{"en":"A grammar rule","fil":"Tuntunin sa gramatika","correct":false}]$$),
 ($$starter-shs-communication-context$$,$$The phrase “That was interesting” sounds sincere in one situation and sarcastic in another. What should a listener consider?$$,$$Tapat ang dating ng “Kawili-wili iyon” sa isang sitwasyon ngunit mapanukso sa iba. Ano ang dapat isaalang-alang ng tagapakinig?$$,$$Context, including situation, relationship, and tone, can change how a message is understood.$$,$$Maaaring magbago ang kahulugan ng mensahe dahil sa konteksto gaya ng sitwasyon, ugnayan, at tono.$$,$$[{"en":"The communication context","fil":"Konteksto ng komunikasyon","correct":true},{"en":"The spelling of the speaker’s name","fil":"Baybay ng pangalan ng nagsasalita","correct":false},{"en":"The message length alone","fil":"Haba lamang ng mensahe","correct":false},{"en":"The receiver’s clothing color","fil":"Kulay ng damit ng tagatanggap","correct":false}]$$),
 ($$starter-shs-communication-listening$$,$$A classmate explains a concern. Which response best shows active listening?$$,$$Nagpapaliwanag ng alalahanin ang kaklase. Aling tugon ang pinakamahusay na nagpapakita ng aktibong pakikinig?$$,$$Active listening involves attention and a thoughtful response, such as paraphrasing or asking a relevant question.$$,$$Kabilang sa aktibong pakikinig ang pagbibigay-pansin at makabuluhang tugon gaya ng pagbubuod o pagtatanong nang may kaugnayan.$$,$$[{"en":"Listen without interrupting, then summarize and ask a relevant question.","fil":"Makinig nang hindi sumasabat, pagkatapos ay ibuod at magtanong nang may kaugnayan.","correct":true},{"en":"Plan your reply while ignoring the speaker.","fil":"Pag-isipan ang isasagot habang hindi pinapansin ang nagsasalita.","correct":false},{"en":"Change the topic immediately.","fil":"Agad palitan ang paksa.","correct":false},{"en":"Repeat unrelated advice louder.","fil":"Ulitin nang malakas ang walang kaugnayang payo.","correct":false}]$$),
 ($$starter-shs-communication-feedback$$,$$After giving directions, a teacher asks learners to explain the first step in their own words. What is the teacher checking?$$,$$Pagkatapos magbigay ng tagubilin, pinapaliwanag ng guro sa mga mag-aaral ang unang hakbang sa sarili nilang salita. Ano ang sinusuri ng guro?$$,$$Feedback indicates whether the message was understood as intended.$$,$$Ipinakikita ng feedback kung naunawaan ang mensahe ayon sa nilalayong kahulugan.$$,$$[{"en":"Whether the directions were understood","fil":"Kung naunawaan ang mga tagubilin","correct":true},{"en":"Whether the classroom is large enough","fil":"Kung sapat ang laki ng silid-aralan","correct":false},{"en":"Whether the message was sent twice","fil":"Kung dalawang beses ipinadala ang mensahe","correct":false},{"en":"Whether the speaker used a microphone","fil":"Kung gumamit ng mikropono ang nagsasalita","correct":false}]$$),
 ($$starter-shs-communication-audience$$,$$A student presents the same research to Grade 5 pupils and to a panel of specialists. What should change between presentations?$$,$$Ipinapaliwanag ng mag-aaral ang parehong pananaliksik sa mga mag-aaral sa Grade 5 at sa lupon ng mga espesyalista. Ano ang dapat baguhin?$$,$$Effective communicators adapt wording, detail, and examples to the audience and purpose.$$,$$Inaangkop ng mahusay na tagapagpahayag ang salita, detalye, at halimbawa sa tagapakinig at layunin.$$,$$[{"en":"Use age- and knowledge-appropriate language and examples.","fil":"Gumamit ng wikang at halimbawang angkop sa edad at kaalaman.","correct":true},{"en":"Keep every term unexplained for both groups.","fil":"Huwag ipaliwanag ang mga termino sa alinmang pangkat.","correct":false},{"en":"Change the research findings to entertain each group.","fil":"Baguhin ang resulta ng pananaliksik para aliwin ang bawat pangkat.","correct":false},{"en":"Use the same delivery regardless of purpose.","fil":"Gamitin ang parehong paraan anuman ang layunin.","correct":false}]$$),
 ($$starter-shs-communication-intercultural$$,$$In a group with different cultural communication norms, what helps prevent misunderstandings?$$,$$Sa pangkat na may magkakaibang kaugaliang pangkomunikasyon, ano ang nakatutulong maiwasan ang hindi pagkakaunawaan?$$,$$Respectful intercultural communication checks meaning and avoids assuming everyone uses the same norms.$$,$$Sinusuri ng magalang na intercultural communication ang kahulugan at iniiwasang ipagpalagay na pare-pareho ang kaugalian ng lahat.$$,$$[{"en":"Ask respectfully and clarify instead of assuming.","fil":"Magtanong nang magalang at maglinaw sa halip na manghula.","correct":true},{"en":"Treat one’s own norm as universal.","fil":"Ituring na pangkalahatan ang sariling kaugalian.","correct":false},{"en":"Mock unfamiliar expressions.","fil":"Pagtawanan ang di-pamilyar na pananalita.","correct":false},{"en":"Avoid all communication with the group.","fil":"Iwasan ang lahat ng pakikipag-usap sa pangkat.","correct":false}]$$),
 ($$starter-shs-lifeskills-goals$$,$$A learner wants to improve grades but has no plan. Which goal statement is most useful?$$,$$Nais pagandahin ng mag-aaral ang marka ngunit wala siyang plano. Aling pahayag ng layunin ang higit na kapaki-pakinabang?$$,$$A useful goal clearly states an outcome and guides concrete action.$$,$$Malinaw na inilalahad ng kapaki-pakinabang na layunin ang nais makamit at ginagabayan ang mga kongkretong hakbang.$$,$$[{"en":"Raise my Math grade by one level this term by studying 30 minutes on weekdays.","fil":"Itaas ng isang antas ang marka ko sa Math ngayong term sa pamamagitan ng 30 minutong pag-aaral tuwing weekday.","correct":true},{"en":"Do better someday.","fil":"Pagbutihin balang araw.","correct":false},{"en":"Study when I feel like it.","fil":"Mag-aral kapag ginanahan.","correct":false},{"en":"Get perfect results without changing habits.","fil":"Makakuha ng perpektong resulta nang hindi binabago ang gawi.","correct":false}]$$),
 ($$starter-shs-lifeskills-budget$$,$$A student receives a monthly allowance and wants to save for school supplies. Which tool helps plan spending and saving?$$,$$Tumatanggap ng buwanang allowance ang mag-aaral at nais mag-ipon para sa gamit sa paaralan. Anong kasangkapan ang tutulong magplano ng gastos at ipon?$$,$$A budget plans expected income and how it will be spent or saved.$$,$$Pinaplano ng budget ang inaasahang kita at kung paano ito gagastusin o iipunin.$$,$$[{"en":"A budget","fil":"Budget","correct":true},{"en":"A shopping list with no prices","fil":"Listahan ng bibilhin na walang presyo","correct":false},{"en":"A loan agreement","fil":"Kasunduan sa pautang","correct":false},{"en":"A receipt from last month only","fil":"Resibo noong nakaraang buwan lamang","correct":false}]$$),
 ($$starter-shs-lifeskills-emergency-savings$$,$$A family suddenly needs to pay for a broken water pump. Which savings are intended for unexpected costs like this?$$,$$Biglang kailangang magbayad ng pamilya para sa sirang water pump. Aling ipon ang inilaan para sa di-inaasahang gastos?$$,$$Emergency savings provide funds for unexpected costs outside routine spending.$$,$$Naglalaan ang emergency savings ng pondo para sa di-inaasahang gastos na wala sa karaniwang budget.$$,$$[{"en":"Emergency savings","fil":"Ipon para sa emerhensiya","correct":true},{"en":"A vacation fund only","fil":"Pondo para lamang sa bakasyon","correct":false},{"en":"A monthly entertainment budget","fil":"Buwanang budget para sa libangan","correct":false},{"en":"A planned subscription payment","fil":"Planadong bayad sa subscription","correct":false}]$$),
 ($$starter-shs-lifeskills-needs-wants$$,$$A learner has limited money for the week and is deciding between lunch and a new game skin. Which budget choice prioritizes a need?$$,$$Limitado ang pera ng mag-aaral para sa linggo at namimili sa pagitan ng tanghalian at bagong game skin. Aling pasya ang inuuna ang pangangailangan?$$,$$A budget helps distinguish essential needs from optional wants and savings goals.$$,$$Tumutulong ang budget na pag-ibahin ang mahahalagang pangangailangan, mga kagustuhan, at layunin sa pag-iipon.$$,$$[{"en":"Set aside money for lunch before optional entertainment.","fil":"Maglaan muna para sa tanghalian bago sa opsyonal na libangan.","correct":true},{"en":"Spend the full amount on the game skin.","fil":"Gastusin ang buong pera sa game skin.","correct":false},{"en":"Ignore food until the week ends.","fil":"Huwag kumain hanggang matapos ang linggo.","correct":false},{"en":"Borrow without considering repayment.","fil":"Mangutang nang hindi iniisip ang pagbabayad.","correct":false}]$$),
 ($$starter-shs-lifeskills-career$$,$$A learner enjoys solving puzzles and is good at explaining ideas. What is a useful first step in career exploration?$$,$$Mahilig lutasin ang palaisipan at mahusay magpaliwanag ng ideya ang mag-aaral. Ano ang kapaki-pakinabang na unang hakbang sa paggalugad ng karera?$$,$$Career exploration compares interests and skills with the tasks and requirements of different work.$$,$$Inihahambing sa career exploration ang interes at kasanayan sa mga gawain at pangangailangan ng iba’t ibang trabaho.$$,$$[{"en":"Research careers that use both strengths and interests.","fil":"Magsaliksik ng mga karerang gumagamit ng kakayahan at interes.","correct":true},{"en":"Choose a job only because a friend chose it.","fil":"Pumili ng trabaho dahil pinili ito ng kaibigan.","correct":false},{"en":"Ignore the skills required for a job.","fil":"Balewalain ang kasanayang kailangan sa trabaho.","correct":false},{"en":"Assume interests can never change.","fil":"Ipagpalagay na hindi nagbabago ang interes.","correct":false}]$$),
 ($$starter-shs-lifeskills-adaptability$$,$$A project’s requirements change after new information arrives. Which response demonstrates adaptability?$$,$$Nagbago ang mga pangangailangan ng proyekto matapos makatanggap ng bagong impormasyon. Aling tugon ang nagpapakita ng adaptability?$$,$$Adaptability means adjusting plans or actions when circumstances change.$$,$$Ang adaptability ay pag-aangkop ng plano o kilos kapag nagbabago ang kalagayan.$$,$$[{"en":"Revise the plan and learn the new requirements.","fil":"Baguhin ang plano at alamin ang bagong pangangailangan.","correct":true},{"en":"Continue the outdated plan without review.","fil":"Ipagpatuloy ang lumang plano nang hindi sinusuri.","correct":false},{"en":"Refuse to consider any new information.","fil":"Tumangging isaalang-alang ang bagong impormasyon.","correct":false},{"en":"Blame teammates and stop participating.","fil":"Sisihin ang kakampi at tumigil sa pakikilahok.","correct":false}]$$),
 ($$starter-shs-lifeskills-teamwork$$,$$A group has a shared deadline, but tasks overlap and some work is missed. What teamwork step would help?$$,$$May iisang deadline ang pangkat ngunit nagkakapatong ang gawain at may nakakaligtaan. Anong hakbang sa teamwork ang makatutulong?$$,$$Teamwork requires coordinating individual efforts toward the group’s shared goal.$$,$$Nangangailangan ang teamwork ng pag-uugnay ng mga gawain ng bawat isa para sa iisang layunin.$$,$$[{"en":"Agree on roles, check progress, and coordinate tasks.","fil":"Magkasundo sa tungkulin, subaybayan ang progreso, at pag-ugnayin ang gawain.","correct":true},{"en":"Let everyone assume someone else will do it.","fil":"Ipagpalagay na ibang tao ang gagawa.","correct":false},{"en":"Keep plans private from teammates.","fil":"Itago sa kakampi ang plano.","correct":false},{"en":"Compete to finish unrelated tasks first.","fil":"Mag-unahan sa paggawa ng walang kaugnayang gawain.","correct":false}]$$),
 ($$starter-shs-lifeskills-spending$$,$$At month’s end, a student wants to know why savings were lower than planned. What record is most useful?$$,$$Sa katapusan ng buwan, nais malaman ng mag-aaral kung bakit mas mababa sa plano ang naipon. Anong tala ang pinakamakikinabang?$$,$$Tracking actual spending makes it possible to compare expenses with the budget plan.$$,$$Nagagamit ang tala ng aktuwal na gastos upang ihambing ang mga ito sa plano ng budget.$$,$$[{"en":"A record of actual expenses during the month","fil":"Talaan ng aktuwal na gastusin sa buong buwan","correct":true},{"en":"A list of future purchases only","fil":"Listahan lamang ng mga bibilhin sa hinaharap","correct":false},{"en":"A friend’s budget","fil":"Budget ng kaibigan","correct":false},{"en":"A total income figure without expense details","fil":"Kabuuang kita na walang detalye ng gastos","correct":false}]$$),
 ($$starter-shs-lifeskills-decision$$,$$Two phone plans meet a learner’s needs, but one costs less over a year. What comparison supports an informed choice?$$,$$Natugunan ng dalawang phone plan ang pangangailangan ng mag-aaral ngunit mas mura ang isa sa loob ng isang taon. Anong paghahambing ang makatutulong sa matalinong pasya?$$,$$Comparing total costs with needs helps people choose based on value and affordability.$$,$$Nakatutulong ang paghahambing ng kabuuang gastos at pangangailangan upang pumili ayon sa halaga at kakayahang magbayad.$$,$$[{"en":"Compare total yearly cost and needed features.","fil":"Ihambing ang kabuuang gastos sa isang taon at mga kailangang feature.","correct":true},{"en":"Choose the plan with the flashiest advertisement.","fil":"Piliin ang planong may pinakamagarbong patalastas.","correct":false},{"en":"Ignore fees and contract length.","fil":"Balewalain ang bayarin at haba ng kontrata.","correct":false},{"en":"Pick randomly without checking requirements.","fil":"Pumili nang sapalaran nang hindi sinusuri ang pangangailangan.","correct":false}]$$),
 ($$starter-shs-history-archipelago$$,$$A student reads Article I of the 1987 Constitution to identify the country’s territory. Which description does it include?$$,$$Binabasa ng mag-aaral ang Artikulo I ng 1987 Konstitusyon upang tukuyin ang teritoryo ng bansa. Aling paglalarawan ang kabilang dito?$$,$$The Constitution describes national territory as including the Philippine archipelago and its waters.$$,$$Inilalarawan ng Konstitusyon na kabilang sa pambansang teritoryo ang kapuluan ng Pilipinas at mga tubig nito.$$,$$[{"en":"The Philippine archipelago and its waters","fil":"Kapuluan ng Pilipinas at mga tubig nito","correct":true},{"en":"Only the largest islands","fil":"Pinakamalalaking pulo lamang","correct":false},{"en":"All of Southeast Asia","fil":"Buong Timog-silangang Asya","correct":false},{"en":"Only land within city boundaries","fil":"Lupain lamang sa loob ng mga hangganan ng lungsod","correct":false}]$$),
 ($$starter-shs-history-independence$$,$$A timeline asks where independence was proclaimed on June 12, 1898. Which place should be cited?$$,$$Itinatanong sa timeline kung saan ipinahayag ang kasarinlan noong Hunyo 12, 1898. Aling lugar ang dapat banggitin?$$,$$The proclamation of independence took place in Kawit, Cavite.$$,$$Ipinahayag ang kasarinlan sa Kawit, Cavite.$$,$$[{"en":"Kawit, Cavite","fil":"Kawit, Cavite","correct":true},{"en":"Malolos, Bulacan","fil":"Malolos, Bulacan","correct":false},{"en":"Alapan, Imus","fil":"Alapan, Imus","correct":false},{"en":"Dapitan, Zamboanga del Norte","fil":"Dapitan, Zamboanga del Norte","correct":false}]$$),
 ($$starter-shs-history-flag$$,$$A museum exhibit describes the first raising of the Philippine flag during battle. Which event detail is accurate?$$,$$Inilalarawan ng eksibit sa museo ang unang pagwawagayway ng watawat ng Pilipinas sa labanan. Aling detalye ang tama?$$,$$The flag was first raised in battle at Alapan on May 28, 1898.$$,$$Unang iwinagayway sa labanan ang watawat sa Alapan noong Mayo 28, 1898.$$,$$[{"en":"At Alapan on May 28, 1898","fil":"Sa Alapan noong Mayo 28, 1898","correct":true},{"en":"At Kawit on June 12, 1898","fil":"Sa Kawit noong Hunyo 12, 1898","correct":false},{"en":"At Malolos on February 2, 1987","fil":"Sa Malolos noong Pebrero 2, 1987","correct":false},{"en":"At Manila on July 4, 1946","fil":"Sa Maynila noong Hulyo 4, 1946","correct":false}]$$),
 ($$starter-shs-history-constitution-ratified$$,$$A civics timeline distinguishes adoption from ratification. When was the 1987 Constitution ratified by plebiscite?$$,$$Ibinubukod ng timeline sa civics ang pagpapatibay sa ibang pangyayari. Kailan pinagtibay sa plebisito ang 1987 Konstitusyon?$$,$$The 1987 Constitution was ratified by plebiscite on February 2, 1987.$$,$$Pinagtibay sa plebisito ang 1987 Konstitusyon noong Pebrero 2, 1987.$$,$$[{"en":"February 2, 1987","fil":"Pebrero 2, 1987","correct":true},{"en":"June 12, 1898","fil":"Hunyo 12, 1898","correct":false},{"en":"May 28, 1898","fil":"Mayo 28, 1898","correct":false},{"en":"January 21, 1973","fil":"Enero 21, 1973","correct":false}]$$),
 ($$starter-shs-history-primary-source$$,$$A researcher compares a diary written during a revolution with a modern encyclopedia. Which item is a primary source?$$,$$Inihahambing ng mananaliksik ang talaarawang isinulat noong himagsikan at makabagong ensiklopedya. Alin ang primary source?$$,$$A diary created during the period being studied is a primary source.$$,$$Primary source ang talaarawang nilikha noong panahong pinag-aaralan.$$,$$[{"en":"The contemporary diary","fil":"Ang talaarawang isinulat noong panahong iyon","correct":true},{"en":"The modern encyclopedia article","fil":"Makabagong artikulo sa ensiklopedya","correct":false},{"en":"A recent summary written without original evidence","fil":"Bagong buod na walang orihinal na ebidensiya","correct":false},{"en":"A fictional story set in that era","fil":"Kathang-isip na kuwentong itinakda sa panahong iyon","correct":false}]$$),
 ($$starter-shs-history-culture$$,$$A learner interviews elders about a community festival and compares the accounts with historical records. What can this study connect?$$,$$Iniinterbyu ng mag-aaral ang matatanda tungkol sa pista ng komunidad at inihahambing ang salaysay sa mga tala ng kasaysayan. Ano ang naiuugnay ng pag-aaral?$$,$$Studying culture can connect historical awareness with community and lived experience.$$,$$Naiuugnay ng pag-aaral ng kultura ang kamalayang pangkasaysayan sa komunidad at aktuwal na karanasan.$$,$$[{"en":"Historical understanding with community culture and experience","fil":"Pag-unawa sa kasaysayan sa kultura at karanasan ng komunidad","correct":true},{"en":"Historical dates with weather forecasts","fil":"Mga petsa sa kasaysayan sa ulat-panahon","correct":false},{"en":"A community’s traditions with unrelated fictional events","fil":"Tradisyon ng komunidad sa walang kaugnayang kathang pangyayari","correct":false},{"en":"Personal preference with a map scale","fil":"Personal na kagustuhan sa scale ng mapa","correct":false}]$$),
 ($$starter-shs-history-island-groups$$,$$A national report groups the Philippines into its three broad island regions. Which classification is standard?$$,$$Hinahati ng pambansang ulat ang Pilipinas sa tatlong malalawak na pangkat ng pulo. Aling pag-uuri ang karaniwan?$$,$$The three major island groups are Luzon, Visayas, and Mindanao.$$,$$Luzon, Visayas, at Mindanao ang tatlong pangunahing pangkat ng pulo.$$,$$[{"en":"Luzon, Visayas, and Mindanao","fil":"Luzon, Visayas, at Mindanao","correct":true},{"en":"Luzon, Borneo, and Sulawesi","fil":"Luzon, Borneo, at Sulawesi","correct":false},{"en":"Palawan, Cebu, and Leyte only","fil":"Palawan, Cebu, at Leyte lamang","correct":false},{"en":"North, Central, and South Philippines","fil":"Hilaga, Gitna, at Timog Pilipinas","correct":false}]$$),
 ($$starter-shs-history-constitution$$,$$A government office checks which charter currently establishes the Republic’s governing framework. Which document is in force?$$,$$Sinusuri ng tanggapan ng pamahalaan kung aling saligang-batas ang kasalukuyang nagtatakda sa balangkas ng Republika. Aling dokumento ang umiiral?$$,$$The 1987 Constitution is the present Constitution of the Republic of the Philippines.$$,$$Ang 1987 Konstitusyon ang kasalukuyang Konstitusyon ng Republika ng Pilipinas.$$,$$[{"en":"The 1987 Constitution","fil":"1987 Konstitusyon","correct":true},{"en":"The Malolos Constitution only","fil":"Konstitusyon ng Malolos lamang","correct":false},{"en":"The 1899 Treaty of Paris","fil":"Kasunduan sa Paris noong 1899","correct":false},{"en":"The 1935 Constitution as the current charter","fil":"Konstitusyon ng 1935 bilang kasalukuyang saligang-batas","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,explanation_en,explanation_fil,options)
WHERE c.content_key=v.content_key;
